#pragma once

#include <QString>
#include <QStringList>
#include <QVector>

// Practice mode: the app shows a character, the writer writes it, and the sample is saved with the
// prompt as its label (no typing). Prompt lists come from docs/practice-sets.json (generated by
// scripts/make_practice_sets.py) and the categories of docs/sample-chars.json. UI-free, so it can be
// tested without a display.

struct PracticeSet {
  QString id;           // "core", "dev-extra", "list-simple", ...
  QString label;
  QString tag;          // sample set it writes to: "dev", "test" or "textbook"
  QString description;
  QStringList chars;    // one entry per character (a code point, possibly a surrogate pair)
};

namespace practice {

// All sets found under docsDir (practice-sets.json, then sample-chars.json as "list-<category>"
// sets with tag "dev"). Missing files are skipped; *error is set only if neither exists.
QVector<PracticeSet> loadSets(const QString& docsDir, QString* error = nullptr);

// Directory a sample with this tag is saved in: $HANDWRITING_SAMPLES_DIR if set (everything goes
// there), else a sibling of defaultSamplesDir: dev -> samples, test -> samples-test,
// textbook -> samples-textbook.
QString sampleDirForTag(const QString& tag, const QString& defaultSamplesDir);

// Characters this writer has already written into `dir` (any set). A writer is identified by the
// "writer" field of the sample files; samples without one (version 1) belong to nobody.
QStringList charsWrittenBy(const QString& dir, const QString& writer);

// A pass through one set for one writer. Characters already written are not offered again, so
// closing the app and coming back resumes where the writer stopped. The order is shuffled
// deterministically from the writer and set, so two writers see different orders.
class PracticeSession {
 public:
  PracticeSession(const PracticeSet& set, const QString& writer, const QStringList& alreadyWritten);

  const PracticeSet& set() const { return set_; }
  QString current() const { return queue_.isEmpty() ? QString() : queue_.first(); }
  bool finished() const { return queue_.isEmpty(); }
  int total() const { return set_.chars.size(); }
  int written() const { return total() - queue_.size(); }
  int remaining() const { return queue_.size(); }

  // The current character was saved to `path`: move on.
  void saved(const QString& path);
  // Defer the current character to the end of the queue (it is offered again later).
  void skip();
  // Delete the sample saved last in this session and offer its character again. False if none.
  bool undoLastSaved(QString* removedPath = nullptr);

 private:
  PracticeSet set_;
  QStringList queue_;
  struct Saved {
    QString character;
    QString path;
  };
  QVector<Saved> savedThisSession_;
};

}  // namespace practice
